+<?php
+declare(strict_types=1);
+
+namespace WP_Rocket\Tests\Integration\inc\Engine\Common\JobManager\Cron\Subscriber;
+
+use WP_Rocket\Tests\Integration\TestCase;
+
+/**
+ * Test class covering \WP_Rocket\Engine\Common\JobManager\Cron\Subscriber::initialize_rucss_queue_runner
+ *
+ * @group JobManager
+ */
+class Test_InitializeRucssQueueRunner extends TestCase {
+	/**
+	 * Value for the remove_unused_css option, set per test case.
+	 *
+	 * @var int
+	 */
+	private $rucss;
+
+	/**
+	 * Isolate the callback under test and clean up after each case.
+	 *
+	 * @return void
+	 */
+	public function set_up() {
+		parent::set_up();
+
+		$this->unregisterAllCallbacksExcept( 'init', 'initialize_rucss_queue_runner' );
+	}
+
+	/**
+	 * Remove filters and scheduled events added during the test.
+	 *
+	 * @return void
+	 */
+	public function tear_down() {
+		$this->restoreWpHook( 'init' );
+
+		remove_filter( 'pre_get_rocket_option_remove_unused_css', [ $this, 'set_rucss_option' ] );
+		remove_filter( 'rocket_rocket_insights_enabled', '__return_false' );
+		remove_filter( 'rocket_rocket_insights_enabled', '__return_true' );
+
+		wp_clear_scheduled_hook( 'action_scheduler_run_queue_rucss', [ 'WP Cron' ] );
+
+		parent::tear_down();
+	}
+
+	/**
+	 * Verifies queue runner scheduling based on RUCSS and Rocket Insights enabled states.
+	 *
+	 * @dataProvider configTestData
+	 *
+	 * @param array $config   Test configuration (remove_unused_css, rocket_insights_enabled).
+	 * @param bool  $expected Whether action_scheduler_run_queue_rucss should be scheduled.
+	 */
+	public function testShouldDoExpected( $config, $expected ) {
+		$this->rucss = $config['remove_unused_css'];
+
+		add_filter( 'pre_get_rocket_option_remove_unused_css', [ $this, 'set_rucss_option' ] );
+		add_filter(
+			'rocket_rocket_insights_enabled',
+			$config['rocket_insights_enabled'] ? '__return_true' : '__return_false'
+		);
+
+		// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound -- Triggering a WordPress core hook.
+		do_action( 'init' );
+
+		if ( $expected ) {
+			$this->assertNotFalse( wp_next_scheduled( 'action_scheduler_run_queue_rucss', [ 'WP Cron' ] ) );
+		} else {
+			$this->assertFalse( wp_next_scheduled( 'action_scheduler_run_queue_rucss', [ 'WP Cron' ] ) );
+		}
+	}
+
+	/**
+	 * Returns the remove_unused_css option value for the current test.
+	 *
+	 * @return int
+	 */
+	public function set_rucss_option() {
+		return $this->rucss;
+	}
+}
